        double *p2 = (i == len - 1) ? points[0] : points[i + 1];
        double a = p1[0] * p2[1] - p2[0] * p1[1];
        cx += (p1[0] + p2[0]) * a;
        cy += (p1[1] + p2[1]) * a;
        ar += a;
