                    overlap = radius - dist;
                }
            }
        }
        else if (region == 1)
        {
            satc_point_copy(edge, polygon->edges[next]);
            satc_point_copy(point, circle_pos);
            satc_point_sub(point, points[next]);
            region = satc_voronoi_region(edge, point);
            if (region == -1)
            {
                double dist = sqrt(point[0] * point[0] + point[1] * point[1]);
                if (dist > radius)
